-- Synthetic district heating network for Nuremberg. Do not edit by hand.
--
-- Author:      Karin Patenge
-- Last update: 2026-11-13
--
-- Idempotent: rows are merged by key. Twin OCIDs, health status, telemetry,
-- anomalies and work orders are kept.
--
-- Parallel DML is disabled for this session: all MERGE statements run in one
-- transaction, and a parallel MERGE into a table already changed in that
-- transaction fails with ORA-12839 (for example on the _high or _medium
-- service of Autonomous AI Database, where parallel DML is on by default).

SET DEFINE OFF
-- The parallel DML state can only change outside a transaction (ORA-12841):
-- end an open one first, for example from an earlier, failed run.
COMMIT;
ALTER SESSION DISABLE PARALLEL DML;

